async (page) => {
    const checks = [];
    const check = (ok, name) => { if (!ok) throw new Error(name); checks.push(name); };
    const toggle = page.getByRole('switch', {name:'Modo claro'});
    check(await page.title() === 'Yasmin | DevLinks', 'Título personalizado');
    await page.getByRole('img',{name:'Avatar de Yasmin no GitHub'}).evaluate(img => img.decode());
    check(await toggle.getAttribute('aria-checked') === 'false', 'Tema inicial escuro');
    await toggle.click();
    check(await toggle.getAttribute('aria-checked') === 'true', 'Alterna para claro');
    await page.reload();
    check(await toggle.getAttribute('aria-checked') === 'true', 'Claro persiste após recarregar');
    await toggle.focus(); await page.keyboard.press('Space');
    check(await toggle.getAttribute('aria-checked') === 'false', 'Teclado alterna para escuro');
    await page.reload();
    check(await toggle.getAttribute('aria-checked') === 'false', 'Escuro persiste após recarregar');
    const links = page.getByRole('navigation',{name:'Links de Yasmin'}).getByRole('link');
    check(await links.count() === 4, 'Quatro botões');
    const expected = ['https://github.com/yaascarol','https://github.com/yaascarol?tab=repositories','https://github.com/yaascarol/ProjetoCurrencyExchangeApp','https://github.com/yaascarol?tab=stars'];
    for(let i=0;i<4;i++) {
      const a=links.nth(i);
      check(await a.getAttribute('href') === expected[i], 'Destino botão '+(i+1));
      check(await a.getAttribute('target') === '_blank' && (await a.getAttribute('rel')).includes('noopener'), 'Nova aba segura '+(i+1));
      const popupPromise = page.waitForEvent('popup'); await a.click(); const popup = await popupPromise;
      await popup.waitForURL(expected[i], {waitUntil:'domcontentloaded'});
      check(popup.url() === expected[i], 'Abriu destino '+(i+1)); await popup.close();
    }
    return {passed:true, checks};
  }

